# Load grids to keep track
import os, re

def load_session_grids():
    d = os.environ.get('RLM_SESSION_DIR')
    if not d:
        return {}
    session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    try:
        t = open(session_file).read().replace('\\n', '\n')
        G = {}
        pattern = re.compile(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n')
        for m in pattern.finditer(t):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows = []
            rest = t[m.end():].split('\n')[:h]
            for r in rest:
                match = re.match(r'\s*(\d+)\s+(\d+)\s+(.*)', r)
                if match and match.groups():
                    pass
            # Find digit-only rows
            rows = [re.findall(r'\d+', r) for r in rest if re.search(r'\d+', r)]
            if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                if rows:
                    G[k] = [[int(x) for x in r] for r in rows]
        return G
    except:
        return {}

G = load_session_grids()
print("Sessions loaded:", list(G.keys()))
for k, v in G.items():
    print(f"\n{k}: {v}")

